package com.arakaki.prismapdf;
import android.content.*;import android.database.*;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.provider.OpenableColumns;import android.webkit.MimeTypeMap;import java.io.*;
public class SharedFileProvider extends ContentProvider {
 public boolean onCreate(){return true;}
 private File resolve(Uri uri)throws IOException{String name=uri.getLastPathSegment();if(!(getContext().getPackageName()+".files").equals(uri.getAuthority())||name==null||name.contains("/")||name.contains("\\")||name.equals(".")||name.equals(".."))throw new FileNotFoundException();boolean capture=uCapture(uri);if(!capture&&uri.getPathSegments().size()!=1)throw new FileNotFoundException();File root=new File(getContext().getCacheDir(),capture?"captures":"exports").getCanonicalFile(),f=new File(root,name).getCanonicalFile();if(!root.equals(f.getParentFile())||!f.isFile())throw new FileNotFoundException();return f;}
 private boolean uCapture(Uri uri){java.util.List<String> parts=uri.getPathSegments();return parts.size()==2&&"capture".equals(parts.get(0));}
 public ParcelFileDescriptor openFile(Uri u,String mode)throws FileNotFoundException{try{int flags=ParcelFileDescriptor.MODE_READ_ONLY;if(!"r".equals(mode)){if(!uCapture(u)||!("w".equals(mode)||"wt".equals(mode)||"rw".equals(mode)||"rwt".equals(mode)))throw new FileNotFoundException();flags=ParcelFileDescriptor.MODE_READ_WRITE;if(mode.contains("t")||"w".equals(mode))flags|=ParcelFileDescriptor.MODE_TRUNCATE;}return ParcelFileDescriptor.open(resolve(u),flags);}catch(IOException e){throw new FileNotFoundException();}}
 public String getType(Uri u){String name=u.getLastPathSegment();if(name==null)return "application/octet-stream";String ext=name.substring(name.lastIndexOf('.')+1).toLowerCase(java.util.Locale.ROOT);String mime=MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext);return mime==null?"application/octet-stream":mime;}
 public Cursor query(Uri u,String[] projection,String selection,String[] args,String order){try{File file=resolve(u);String[] columns=projection==null?new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE}:projection;MatrixCursor cursor=new MatrixCursor(columns);Object[] values=new Object[columns.length];for(int i=0;i<columns.length;i++)values[i]=OpenableColumns.DISPLAY_NAME.equals(columns[i])?file.getName():OpenableColumns.SIZE.equals(columns[i])?file.length():null;cursor.addRow(values);return cursor;}catch(IOException e){return null;}}
 public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}
}
